import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String text = new String(System.in.readAllBytes()).strip();
        long count = 0;
        if (!text.isEmpty())
            for (String w : text.split("\\s+"))
                if (Character.toLowerCase(w.charAt(0)) == Character.toLowerCase(w.charAt(w.length() - 1))) count++;
        System.out.println(count);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
	"unicode"
)

func main() {
	raw, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	count := 0
	for _, w := range strings.Fields(string(raw)) {
		if unicode.ToLower(rune(w[0])) == unicode.ToLower(rune(w[len(w)-1])) {
			count++
		}
	}
	fmt.Println(count)
}
